<script>$(function(){let chart=null;const type='<?= $type ?>',money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');function filters(){let p={};$('.filter').each(function(){p[$(this).data('key')]=$(this).val()});return p}function load(){$('#tbody').html('<tr><td class="empty-state">Memuat laporan...</td></tr>');$.post('<?= base_url('laporan/result/') ?>'+type,filters(),r=>{if(r.result!=='true')return Swal.fire('Gagal',r.message,'error');let keys=Object.keys(r.columns),moneyKeys=r.money||[];$('#thead').html('<tr><th>No</th>'+keys.map(k=>`<th class="${moneyKeys.includes(k)?'text-end':''}">${escapeHtml(r.columns[k])}</th>`).join('')+'</tr>');$('#tbody').html(r.rows.length?r.rows.map((x,i)=>'<tr><td>'+(i+1)+'</td>'+keys.map(k=>`<td class="${moneyKeys.includes(k)?'text-end':''}">${moneyKeys.includes(k)?money(x[k]):escapeHtml(x[k]??'')}</td>`).join('')+'</tr>').join(''):`<tr><td colspan="${keys.length+1}" class="empty-state">Tidak ada data sesuai filter.</td></tr>`);$('#summary').html(Object.entries(r.summary||{}).map(([k,v])=>`<div class="col-md-3"><div class="card"><div class="card-body"><small>${escapeHtml(k)}</small><h5 class="mb-0">${/target|pembayaran|sisa|tunggakan|dibatalkan/i.test(k)?money(v):escapeHtml(v)}</h5></div></div></div>`).join(''));if(r.chart&&r.chart.labels&&r.chart.labels.length){$('#chartCard').removeClass('d-none');if(chart)chart.destroy();chart=new ApexCharts(document.querySelector('#chart'),{chart:{type:'bar',height:330,toolbar:{show:false}},series:r.chart.series,xaxis:{categories:r.chart.labels},dataLabels:{enabled:false},yaxis:{labels:{formatter:v=>Number(v).toLocaleString('id-ID')}},tooltip:{y:{formatter:v=>money(v)}}});chart.render()}else{$('#chartCard').addClass('d-none');if(chart){chart.destroy();chart=null}}},'json').fail(ajaxError)}$('#tampil').click(load);$('#reset').click(()=>location.reload());$('#export').click(function(){this.href='<?= base_url('laporan/export/') ?>'+type+'?'+new URLSearchParams(filters()).toString()});load()});</script>
